decor.endfield:
/* 谷地黄：斜切角 + 硬边 + 工程刻度 */
.block { border-radius: 0 !important; clip-path: polygon(0 0, calc(100% - 9px) 0, 100% 9px, 100% 100%, 0 100%); }
.block::after { content: ""; position: absolute; right: 0; top: 0; width: 9px; height: 9px; background: linear-gradient(135deg, var(--accent) 0 42%, transparent 50%); pointer-events: none; }
.timeline .head { box-shadow: inset 3px 0 0 var(--accent); }
.day-head { font-family: var(--font-mono); letter-spacing: .1em; text-transform: uppercase; }
.backlog .head { box-shadow: inset 3px 0 0 var(--accent); }

decor.terminal:
/* 终端：HUD 角标 + 磷光 */
.block { border-radius: 0 !important; box-shadow: 0 0 0 1px color-mix(in srgb, var(--accent) 45%, transparent), 0 0 12px color-mix(in srgb, var(--accent) 16%, transparent); }
.block::before, .block::after { content: ""; position: absolute; width: 7px; height: 7px; border: 1px solid var(--accent); pointer-events: none; }
.block::before { left: -1px; top: -1px; border-right: 0; border-bottom: 0; }
.block::after { right: -1px; bottom: -1px; border-left: 0; border-top: 0; }
.day-head { font-family: var(--font-mono); letter-spacing: .14em; }
.timeline .head { box-shadow: inset 0 -1px 0 color-mix(in srgb, var(--accent) 55%, transparent); }

decor.artdeco:
/* 装饰艺术：金色双线 + 衬线标题 + 渐隐金线 */
.block { border: 1px solid color-mix(in srgb, var(--medal) 80%, transparent) !important; box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--medal) 26%, transparent); border-radius: 0 !important; }
.day-head { font-family: Georgia, "Times New Roman", "Songti SC", SimSun, serif; letter-spacing: .18em; font-variant: small-caps; }
.timeline .head::after { content: ""; flex: 1; height: 1px; margin-left: 12px; background: linear-gradient(90deg, color-mix(in srgb, var(--medal) 75%, transparent), transparent); }
.backlog .head::after { content: ""; flex: 1; height: 1px; margin-left: 12px; background: linear-gradient(90deg, color-mix(in srgb, var(--medal) 60%, transparent), transparent); }

decor.deepsea:
/* 深海冷光（阿戈尔）：柔光晕 + 圆润感 + Samigirian 小写（= 阿戈尔文字） */
@font-face { font-family: "Samigirian"; src: url("__FONT_SAMIGIRIAN__") format("woff2"); font-display: swap; }
.block { border-radius: 10px !important; box-shadow: 0 0 16px color-mix(in srgb, var(--accent) 18%, transparent), inset 0 0 0 1px color-mix(in srgb, var(--accent) 22%, transparent); }
body::after { content: ""; position: fixed; inset: 0; pointer-events: none; background: radial-gradient(90% 60% at 18% 0%, color-mix(in srgb, var(--accent) 10%, transparent), transparent 70%); }
.day-head, .backlog .title, .pop-title { font-family: "Samigirian", var(--font-ui); text-transform: lowercase; letter-spacing: .04em; }

decor.bauhaus:
/* 包豪斯：粗线 + 块面分割 */
.block { border-width: 2px !important; border-radius: 0 !important; }
.day-head { font-weight: 700; letter-spacing: .02em; }
.timeline .head { box-shadow: inset 0 -3px 0 var(--accent); }
.backlog .head { box-shadow: inset 0 -3px 0 var(--cat-3); }

decor.cassette:
/* 卡带未来：CRT 暗角 + 屏幕边框 */
body::after { content: ""; position: fixed; inset: 0; pointer-events: none; background: radial-gradient(120% 90% at 50% 45%, transparent 58%, rgb(0 0 0 / 0.22)); }
.block { border-radius: 6px !important; box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--accent) 32%, transparent), 0 1px 0 rgb(0 0 0 / 0.2); }
.day-head { font-family: var(--font-mono); letter-spacing: .06em; }

decor.north:
/* 北境极夜：OFL 开源字体 Samigirian（仅拉丁展示字）+ 冷雾细线 */
@font-face { font-family: "Samigirian"; src: url("__FONT_SAMIGIRIAN__") format("woff2"); font-display: swap; }
.day-head, .backlog .title, .pop-title { font-family: "Samigirian", var(--font-ui); letter-spacing: .06em; }
.block { border-radius: 8px !important; }
.timeline .head { box-shadow: inset 0 -1px 0 color-mix(in srgb, var(--accent) 45%, transparent); }

decor.brutal:
/* 野兽派：粗黑边 + 硬投影 */
.block { border: 2px solid var(--text-primary) !important; border-radius: 0 !important; box-shadow: 3px 3px 0 color-mix(in srgb, var(--text-primary) 85%, transparent); }
.day-head { font-weight: 800; letter-spacing: 0; }
.timeline .head { box-shadow: inset 0 -3px 0 var(--text-primary); }

decor.porcelain:
/* 白瓷：单色细线 · 科幻实验室（设计语言参考 RhineLabUI，MIT；块面不叠纹理/渐变） */
.day-head { font-family: var(--font-mono); text-transform: uppercase; letter-spacing: .18em; font-size: 11px; }
.day-head::after { content: ""; display: block; height: 1px; margin-top: 5px; background: color-mix(in srgb, var(--text-primary) 28%, transparent); }
.timeline .head { box-shadow: inset 0 -1px 0 color-mix(in srgb, var(--text-primary) 35%, transparent); }
.backlog .head { box-shadow: inset 0 -1px 0 color-mix(in srgb, var(--text-primary) 28%, transparent); }
.block { background: var(--card) !important; border-radius: 0 !important; border: 1px solid color-mix(in srgb, var(--text-primary) 22%, transparent) !important; box-shadow: inset 3px 0 0 color-mix(in srgb, var(--accent) 85%, transparent) !important; }
.block .cat-bar { height: 2px !important; }
.block .layer-bar { width: 3px !important; }
.backlog .pane .item { border-bottom: 1px solid color-mix(in srgb, var(--text-primary) 8%, transparent); }
.overlay-panel, .sanity-pop { border: 1px solid color-mix(in srgb, var(--text-primary) 16%, transparent) !important; box-shadow: 0 18px 60px rgb(0 0 0 / 0.12) !important; }
